SELECT units_bucket, min_revenue, stddev_revenue FROM (SELECT CASE WHEN units >= 36 THEN 'high' WHEN units >= 18 THEN 'mid' ELSE 'low' END AS units_bucket, MIN(revenue) AS min_revenue, ROUND(STDDEV(revenue), 2) AS stddev_revenue FROM store_sales WHERE units <= 22 GROUP BY CASE WHEN units >= 36 THEN 'high' WHEN units >= 18 THEN 'mid' ELSE 'low' END) AS x WHERE min_revenue < 3500 ORDER BY min_revenue
